mapper.select:
SELECT r.*, u.username as user_name
FROM review r
LEFT JOIN user u ON r.user_id = u.id
WHERE 1=1
AND r.status = #{status}
AND r.product_id = #{productId}
ORDER BY r.create_time DESC
LIMIT #{offset}, #{pageSize}

